"""Synthetic identification, no source history or financial accounts."""
import numpy as np
import pytest
from core import DAY,START,FIT,events,fit,predict,geometry
def test_same_marginals_secondmoments_different_cohits_negative_preserved():
 x=np.tile([-2.,-1.,1.,2.,-2.,-1.,1.,2.],36);ya=np.tile([-2.,-1.,1.,2.,2.,1.,-1.,-2.],36);yb=np.tile([-1.,2.,-2.,1.,-1.,2.,-2.,1.],36);a=np.column_stack([x,ya]);b=np.column_stack([x,yb]);np.testing.assert_array_equal(np.sort(a,axis=0),np.sort(b,axis=0));np.testing.assert_array_equal(a.T@a,b.T@b);np.testing.assert_array_equal(a.sum(0),b.sum(0));ea=events(a[None],np.array([1.5,1.5]));eb=events(b[None],np.array([1.5,1.5]));np.testing.assert_array_equal(ea[:,:-1],eb[:,:-1]);assert ea[0,-1]==.125 and eb[0,-1]==-.125
def test_future_training_threshold_and_scaler_invariance_and_common_maturity():
 rng=np.random.default_rng(834);d=np.arange(START,FIT+10*DAY,DAY);base=rng.normal(size=(len(d),22));scale=np.ones((len(d),5));z=rng.normal(size=(len(d),288,5));y=np.exp(-8+.1*base[:,0]);base[10]=np.nan;m=fit(d,base,scale,z,y,d+2*DAY);ix=np.array(m['train_indices']);assert len(ix)==727 and 10 not in ix and (d[ix]+2*DAY<FIT).all();future=d+2*DAY>=FIT;b=base.copy();b[future]=999;zz=z.copy();zz[future]=999;yy=y.copy();yy[future]=999;assert fit(d,b,scale,zz,yy,d+2*DAY)==m;valid=np.isfinite(base).all(1);p,_=predict(m,base[valid],z[valid]);np.testing.assert_allclose(p['CONTROL'],y[valid],rtol=1e-10);np.testing.assert_allclose(p['CO_TAIL'],y[valid],rtol=1e-10)
def test_zero_event_feature_stops_without_threshold_or_column_rescue():
 rng=np.random.default_rng(42);d=np.arange(START,FIT,DAY);base=rng.normal(size=(len(d),22));scale=np.ones((len(d),5));z=np.zeros((len(d),288,5));y=np.exp(rng.normal(size=len(d)))
 with pytest.raises(AssertionError):fit(d,base,scale,z,y,d+2*DAY)
def test_day_scale_excludes_current_and_future_and_unknown_is_nan():
 rng=np.random.default_rng(61);r=rng.normal(scale=.001,size=(65,288,5));p=np.exp(np.cumsum(r.reshape(-1,5),axis=0)).reshape(r.shape);rv=np.square(r).sum(1);source=dict(five_close=p,previous_close=np.ones(5),RV=np.square(np.diff(np.log(np.vstack([np.ones(5),p.reshape(-1,5)])),axis=0)).reshape(r.shape).sum(1),RV_1m=rv*1.2,jump_share=np.full_like(rv,.1),down_share=np.full_like(rv,.5),price_return=r.sum(1));a=geometry(source);np.testing.assert_allclose(a['scale'][40],np.sqrt(source['RV'][10:40].mean(0)/288));changed={k:v.copy() for k,v in source.items()};changed['five_close'][40:]*=100;rr=np.diff(np.log(np.vstack([np.ones(5),changed['five_close'].reshape(-1,5)])),axis=0).reshape(r.shape);changed['RV']=np.square(rr).sum(1);b=geometry(changed);np.testing.assert_array_equal(a['scale'][:41],b['scale'][:41]);assert np.isnan(a['scale'][:30]).all();z=np.ones((1,288,5));z[0,0,0]=np.nan;assert np.isnan(events(z,np.ones(5))).all()
